/* =========================================================================
   SQL CAP NHAT: TIEU HAO VA DU BAO NHU CAU NGUYEN LIEU (2024 - 2026)
   1. Dam bao day du 4 bang: PhuongPhapDuBao, DuLieuTieuHao, DanhGiaDuBao, DuBao
   2. Nap PhuongPhapDuBao (Holt-Winters cong tinh & nhan tinh, L = 12)
   3. Seed PhieuBanHang (952 don 2024-2026), CT_PhieuBan (4125 dong),
      DuLieuTieuHao (850 dong 01/2024-10/2026),
      DanhGiaDuBao (1700 dong 2024-2026), DuBao (1750 dong 2024-2026)
========================================================================= */
USE [QLKNL_PIZZA];
GO

IF OBJECT_ID('dbo.PhuongPhapDuBao', 'U') IS NULL
BEGIN
    CREATE TABLE PhuongPhapDuBao
    (
        PhuongPhapID INT IDENTITY(1,1) PRIMARY KEY,
        TenPhuongPhap NVARCHAR(100) NOT NULL,
        LoaiMuaVu NVARCHAR(50),
        ChuKyMuaVu INT,
        TrangThai BIT NOT NULL DEFAULT 1
    );
END
GO

IF OBJECT_ID('dbo.DuLieuTieuHao', 'U') IS NULL
BEGIN
    CREATE TABLE DuLieuTieuHao
    (
        TieuHaoID INT IDENTITY(1,1) PRIMARY KEY,
        NguyenLieuID INT NOT NULL,
        DonViID INT NOT NULL,
        KyTieuHao DATE NOT NULL,
        SoLuongTieuHao DECIMAL(18,3) NOT NULL,
        CONSTRAINT FK_DuLieuTieuHao_NguyenLieu FOREIGN KEY (NguyenLieuID) REFERENCES NguyenLieu(NguyenLieuID),
        CONSTRAINT FK_DuLieuTieuHao_DonViTinh FOREIGN KEY (DonViID) REFERENCES DonViTinh(DonViID)
    );
END
GO

IF OBJECT_ID('dbo.DanhGiaDuBao', 'U') IS NULL
BEGIN
    CREATE TABLE DanhGiaDuBao
    (
        DanhGiaID INT IDENTITY(1,1) PRIMARY KEY,
        NguyenLieuID INT NOT NULL,
        PhuongPhapID INT NOT NULL,
        TuKyTrain DATE NOT NULL,
        DenKyTrain DATE NOT NULL,
        TuKyTest DATE NOT NULL,
        DenKyTest DATE NOT NULL,
        MAE DECIMAL(18,4),
        RMSE DECIMAL(18,4),
        MAPE DECIMAL(18,4),
        NgayDanhGia DATETIME DEFAULT GETDATE(),
        CONSTRAINT FK_DanhGiaDuBao_NguyenLieu FOREIGN KEY (NguyenLieuID) REFERENCES NguyenLieu(NguyenLieuID),
        CONSTRAINT FK_DanhGiaDuBao_PhuongPhap FOREIGN KEY (PhuongPhapID) REFERENCES PhuongPhapDuBao(PhuongPhapID)
    );
END
GO

IF OBJECT_ID('dbo.DuBao', 'U') IS NULL
BEGIN
    CREATE TABLE DuBao
    (
        DuBaoID INT IDENTITY(1,1) PRIMARY KEY,
        NguyenLieuID INT NOT NULL,
        PhuongPhapID INT NOT NULL,
        KyDuBao DATE NOT NULL,
        SoLuongDuBao DECIMAL(18,3) NOT NULL,
        LaMoHinhDuocChon BIT NOT NULL DEFAULT 0,
        NgayDuBao DATETIME DEFAULT GETDATE(),
        TrangThai BIT NOT NULL DEFAULT 1,
        CONSTRAINT FK_DuBao_NguyenLieu FOREIGN KEY (NguyenLieuID) REFERENCES NguyenLieu(NguyenLieuID),
        CONSTRAINT FK_DuBao_PhuongPhap FOREIGN KEY (PhuongPhapID) REFERENCES PhuongPhapDuBao(PhuongPhapID)
    );
END
GO

IF NOT EXISTS (SELECT 1 FROM PhuongPhapDuBao)
BEGIN
    INSERT INTO PhuongPhapDuBao (TenPhuongPhap, LoaiMuaVu, ChuKyMuaVu, TrangThai)
    VALUES (N'Holt-Winters cộng tính', N'Additive', 12, 1),
           (N'Holt-Winters nhân tính', N'Multiplicative', 12, 1);
END
GO

DELETE FROM CT_PhieuBan;
DELETE FROM PhieuBanHang;
DELETE FROM DuLieuTieuHao;
DELETE FROM DuBao;
DELETE FROM DanhGiaDuBao;
GO

